class Optimizer_SGD:
    """Gradient descent whose rate follows learning_rate / (1 + decay * iterations).

    The training loop calls pre_update_params() once per step, then update_params(layer)
    once per layer, then post_update_params() once per step.
    """

    def __init__(self, learning_rate=1.0, decay=0.0):
        self.learning_rate = learning_rate
        self.current_learning_rate = learning_rate
        self.decay = decay
        self.iterations = 0

    def pre_update_params(self):
        # The counter is read before it is incremented, so the first step uses learning_rate.
        if self.decay:
            self.current_learning_rate = self.learning_rate / (1.0 + self.decay * self.iterations)

    def update_params(self, layer):
        layer.weights -= self.current_learning_rate * layer.dweights
        layer.biases -= self.current_learning_rate * layer.dbiases

    def post_update_params(self):
        # Once per step, not once per layer.
        self.iterations += 1
